//		Exec(ctx)
func (_c *EvalRunCreate) OnConflictColumns(columns ...string) *EvalRunUpsertOne {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &EvalRunUpsertOne{
		create: _c,
	}
}

