func (u *EvalRunUpsertOne) DoNothing() *EvalRunUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the EvalRunCreate.OnConflict
